using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;
public static class RuinsPartsReview{
 [Serializable]class Probe{public string kind;public float x,y,z;}[Serializable]class Probes{public Probe[] probes;}
 static void Check(bool b,string s){if(!b)throw new Exception(s);}
 static void Shot(Camera c,Vector3 from,Vector3 target,string file){c.transform.position=from;c.transform.LookAt(target);var rt=new RenderTexture(960,720,24);c.targetTexture=rt;for(int i=0;i<3;i++)c.Render();var prev=RenderTexture.active;RenderTexture.active=rt;var t=new Texture2D(960,720,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,960,720),0,0);t.Apply();File.WriteAllBytes(file,t.EncodeToPNG());RenderTexture.active=prev;c.targetTexture=null;UnityEngine.Object.DestroyImmediate(t);UnityEngine.Object.DestroyImmediate(rt);}
 public static void Run(){const string ev="Evidence/Target25Parts";Directory.CreateDirectory(ev);try{
  EditorSceneManager.OpenScene("Assets/RuinsTarget25Output/Room.unity");Physics.SyncTransforms();GameObject intact=GameObject.Find("ruins_20"),broken=GameObject.Find("ruins_21");Check(intact&&broken,"Two formal columns missing");var objects=new[]{intact,broken};var camera=UnityEngine.Object.FindAnyObjectByType<Camera>();camera.orthographic=false;camera.backgroundColor=new Color(.075f,.085f,.1f);var light=UnityEngine.Object.FindObjectsByType<Light>(FindObjectsSortMode.None).First(l=>l.type==LightType.Directional);light.transform.rotation=Quaternion.Euler(38,-28,0);RenderSettings.ambientLight=Color.gray*.75f;
  var probes=JsonUtility.FromJson<Probes>(File.ReadAllText("Assets/Editor/pier-probes.json"));Check(probes.probes.Length==333,"Missing surface probes");float max=0;
  foreach(var p in probes.probes){var go=p.kind=="pier"?intact:broken;var co=go.GetComponent<MeshCollider>();Check(co&&co.sharedMesh==go.GetComponent<MeshFilter>().sharedMesh,"Visual/collider identity");var origin=go.transform.TransformPoint(new Vector3(p.x,6,p.z));Check(co.Raycast(new Ray(origin,Vector3.down),out var hit,8),"Column surface missing "+p.kind);float d=Mathf.Abs(hit.point.y-go.transform.TransformPoint(new Vector3(p.x,p.y,p.z)).y);max=Mathf.Max(max,d);Check(d<.001,"Column Web/native height mismatch "+p.kind+" x="+p.x+" z="+p.z+" expected="+p.y+" actual="+(hit.point.y-go.transform.position.y)+" delta="+d);}
  foreach(var go in objects){var co=go.GetComponent<MeshCollider>();Check(co.Raycast(new Ray(go.transform.position+new Vector3(0,1,-2),Vector3.forward),out var hit,3),"Column body cannot block");Check(!Physics.CheckCapsule(go.transform.position+new Vector3(go==intact?.9f:-.9f,.4f,0),go.transform.position+new Vector3(go==intact?.9f:-.9f,1.4f,0),.2f),"Clear side passage obstructed");}
  Shot(camera,new Vector3(5,7,10),new Vector3(0,4.3f,6),ev+"/columns-close.png");Shot(camera,new Vector3(10,14,13),new Vector3(0,3.8f,0),ev+"/mixed-game.png");light.transform.rotation=Quaternion.Euler(50,200,0);Shot(camera,new Vector3(-5,7,10),new Vector3(0,4.3f,6),ev+"/columns-opposite.png");
  var original=objects.Select(o=>o.GetComponent<MeshRenderer>().sharedMaterial).ToArray();var gray=new Material(Shader.Find("Universal Render Pipeline/Lit"));gray.SetColor("_BaseColor",new Color(.55f,.55f,.55f));gray.SetFloat("_Smoothness",.15f);foreach(var go in objects)go.GetComponent<MeshRenderer>().sharedMaterial=gray;Shot(camera,new Vector3(5,7,10),new Vector3(0,4.3f,6),ev+"/columns-mono.png");for(int i=0;i<2;i++)objects[i].GetComponent<MeshRenderer>().sharedMaterial=original[i];UnityEngine.Object.DestroyImmediate(gray);
  int tested=0;foreach(int count in new[]{9,225}){var group=new GameObject("SharedColumnDiagnostic");var clones=Enumerable.Range(0,count).Select(i=>{var g=UnityEngine.Object.Instantiate(intact,group.transform);g.transform.position=new Vector3(50+(i%15)*2,3,50+(i/15)*2);return g;}).ToArray();var meshes=clones.Select(g=>g.GetComponent<MeshFilter>().sharedMesh).Distinct().ToArray();var mats=clones.Select(g=>g.GetComponent<MeshRenderer>().sharedMaterial).Distinct().ToArray();Check(meshes.Length==1&&mats.Length==1&&clones.All(g=>g.GetComponent<MeshCollider>().sharedMesh==meshes[0]),"Repeated column references multiplied");tested+=count;UnityEngine.Object.DestroyImmediate(group);}
  File.WriteAllText(ev+"/result.json","{\"pass\":true,\"formalColumnKinds\":2,\"surfaceProbes\":333,\"maxHeightDelta\":"+max.ToString(System.Globalization.CultureInfo.InvariantCulture)+",\"bodyBlocks\":true,\"sideClear\":true,\"referenceInstancesTested\":"+tested+",\"meshMaterialShared\":true,\"gpuMeasured\":false,\"mobileMeasured\":false}");EditorApplication.Exit(0);
 }catch(Exception e){File.WriteAllText(ev+"/failure.txt",e.ToString());Debug.LogException(e);EditorApplication.Exit(1);}}
}
